// Sprint 5 Slice E — render the reminder email body.
//
// We render inline (no `react-dom/server` dependency on Next.js
// and no `@react-email/components` in this workflow) because the
// Next.js Route Handler in `app/api/cron/send-reminders` is
// forbidden from importing `react-dom/server`. The HTML is a
// simple, brand-aligned wrapper — same palette as the React
// templates in `apps/web/lib/email/templates/`, kept here so the
// reminder pipeline ships without an extra npm dep.
//
// Inputs (from the Webhook node):
//   $json.body.to, $json.body.locale ('fr'|'en'),
//   $json.body.student_name, $json.body.session_title,
//   $json.body.scheduled_start, $json.body.join_url,
//   $json.body.window ('24h' | '1h').

const brand = '#1f4e8a';      // bleuPlan
const bg    = '#f6f4ef';      // velin
const card  = '#ffffff';
const text  = '#1f2937';
const muted = '#6b7280';
const stack = "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif";

const body = $json.body;
const locale = body.locale === 'en' ? 'en' : 'fr';
const isOneHour = body.window === '1h';

const subject = isOneHour
  ? (locale === 'fr' ? 'Rappel : votre session commence dans 1 heure' : 'Reminder: your session starts in 1 hour')
  : (locale === 'fr' ? 'Rappel : votre session est demain'            : 'Reminder: your session is tomorrow');

const greeting = locale === 'fr' ? `Bonjour ${body.student_name || ''},` : `Hi ${body.student_name || ''},`;

const leadText = isOneHour
  ? (locale === 'fr'
      ? "Votre session commence dans environ 1 heure. Rejoignez le tuteur directement en utilisant le lien ci-dessous."
      : "Your session starts in about 1 hour. Join the tutor directly using the link below.")
  : (locale === 'fr'
      ? "Petit rappel : votre session est prévue demain. Vous trouverez ci-dessous le lien pour rejoindre votre tuteur."
      : "Quick reminder: your session is scheduled for tomorrow. Below is the link to join your tutor.");

const ctaLabel = locale === 'fr' ? 'Rejoindre la session' : 'Join the session';
const footerLine = locale === 'fr'
  ? "Si vous avez un empêchement, merci d'annuler depuis votre tableau de bord."
  : "If you can't make it, please cancel from your dashboard.";

const html = `<!doctype html><html lang="${locale}"><head><meta charset="utf-8"><title>${subject}</title></head>
<body style="margin:0;padding:0;background:${bg};font-family:${stack};color:${text};">
<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:${bg};padding:24px 0;">
  <tr><td align="center">
    <table role="presentation" cellpadding="0" cellspacing="0" width="560" style="background:${card};border:1px solid ${bg};border-radius:8px;overflow:hidden;">
      <tr><td style="background:${brand};color:#ffffff;padding:20px 24px;font-family:${stack};font-size:18px;font-weight:600;">Intégrale</td></tr>
      <tr><td style="padding:24px;font-family:${stack};font-size:15px;line-height:1.55;">
        <p>${greeting}</p>
        <p>${leadText}</p>
        <p><strong>${locale === 'fr' ? 'Session' : 'Session'}:</strong> ${body.session_title || ''}</p>
        <p><strong>${locale === 'fr' ? 'Date' : 'Date'}:</strong> ${body.scheduled_start || ''}</p>
        <p style="margin:32px 0;">
          <a href="${body.join_url || '#'}" style="background:${brand};color:#ffffff;padding:12px 24px;border-radius:6px;text-decoration:none;font-family:${stack};font-size:15px;font-weight:600;display:inline-block;">${ctaLabel}</a>
        </p>
        <p style="color:${muted};font-size:13px;">${footerLine}</p>
      </td></tr>
      <tr><td style="padding:16px 24px;border-top:1px solid ${bg};color:${muted};font-size:12px;font-family:${stack};">© ${new Date().getFullYear()} Intégrale · contact@integrale.example</td></tr>
    </table>
  </td></tr>
</table>
</body></html>`;

const text = [
  greeting,
  leadText,
  `${locale === 'fr' ? 'Session' : 'Session'}: ${body.session_title || ''}`,
  `${locale === 'fr' ? 'Date' : 'Date'}: ${body.scheduled_start || ''}`,
  `${ctaLabel}: ${body.join_url || ''}`,
  footerLine,
].join('\n\n');

return [{ json: { ...body, subject, html, text } }];
